def message(parts):
    body = b''
    for i, payload in enumerate(parts):
        body += b'--' + boundary + b'\r\nContent-Disposition: form-data; name="p%d"' % i
        if i % 2:
            body += b'; filename="sample.bin"\r\nContent-Type: application/octet-stream'
        body += b'\r\nX-Test: metadata\r\n\r\n' + payload + b'\r\n'
    return body + b'--' + boundary + b'--\r\n'

